package com.mps.attendance.model;
import com.mps.organization.model.Organization; import com.mps.schedule.model.ScheduleEvent; import jakarta.persistence.*; import java.time.Instant; import java.util.*;
@Entity @Table(name="attendance_register") public class AttendanceRegister {
 @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="organization_id") private Organization organization; @OneToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="schedule_id") private ScheduleEvent schedule; @Enumerated(EnumType.STRING) @Column(nullable=false,length=24) private AttendanceRegisterStatus status=AttendanceRegisterStatus.DRAFT; @Column(name="finalized_at") private Instant finalizedAt; @Column(name="finalized_by") private UUID finalizedBy; @Column(name="created_by",nullable=false) private UUID createdBy; @Column(name="created_at",nullable=false) private Instant createdAt=Instant.now(); @Column(name="updated_at",nullable=false) private Instant updatedAt=Instant.now(); @Version private long version;
 protected AttendanceRegister(){} public AttendanceRegister(Organization o,ScheduleEvent s,UUID by){organization=o;schedule=s;createdBy=by;}
 public void finalizeRegister(UUID by){if(status==AttendanceRegisterStatus.FINALIZED)throw new IllegalStateException("Attendance register is already finalized.");status=AttendanceRegisterStatus.FINALIZED;finalizedBy=by;finalizedAt=Instant.now();updatedAt=finalizedAt;}
 public UUID getId(){return id;} public Organization getOrganization(){return organization;} public ScheduleEvent getSchedule(){return schedule;} public AttendanceRegisterStatus getStatus(){return status;} public Instant getFinalizedAt(){return finalizedAt;} public UUID getFinalizedBy(){return finalizedBy;} public long getVersion(){return version;}
}
